INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind Antivirenprogramme nur für Viren relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Schützen auch vor anderer Malware"}, {"text": "Ja", "correct": false, "because": "Umfassender Schutz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Antivirenprogrammen?', 3, '[{"text": "Schutz vor Malware", "correct": true, "because": "Erkennt und entfernt Bedrohungen"}, {"text": "Datenmenge maximieren", "correct": false, "because": "Nicht primär"}, {"text": "Schnelle Verarbeitung", "correct": false, "because": "Sicherheit im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktionen haben Antivirenprogramme?', 5, '[{"text": "Virenscans", "correct": true, "because": "Erkennt Schadsoftware"}, {"text": "Echtzeitschutz", "correct": true, "because": "Verhindert Infektionen"}, {"text": "Datenbankdesign", "correct": false, "because": "Nicht relevant"}, {"text": "Visuelle Gestaltung", "correct": false, "because": "Kein Schutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Antivirenprogramme erkennen Malware. b) Sie schützen nur vor bekannten Viren.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Heuristik für neue Bedrohungen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Nutzung von Antivirenprogrammen?', 4, '[{"text": "Regelmäßige Updates", "correct": false, "because": "Wichtig für neuen Schutz"}, {"text": "Scan-Planung", "correct": false, "because": "Erkennt Bedrohungen früh"}, {"text": "Farbschema", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Antivirenprogramme auch Netzwerke schützen?', 2, '[{"text": "Ja", "correct": true, "because": "Manche bieten Netzwerkschutz"}, {"text": "Nein", "correct": false, "because": "Nicht nur lokal"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Mittel ist typisch für Antivirenprogramme?', 3, '[{"text": "Signaturerkennung", "correct": true, "because": "Identifiziert bekannte Malware"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Irrelevant"}, {"text": "Statische IPs", "correct": false, "because": "Kein Schutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bedrohungen erkennen Antivirenprogramme?', 5, '[{"text": "Trojaner", "correct": true, "because": "Häufige Malware"}, {"text": "Spyware", "correct": true, "because": "Datendiebstahl verhindern"}, {"text": "Serverleistung", "correct": false, "because": "Kein Bedrohungstyp"}, {"text": "Unsortierte Daten", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Antivirenprogramme brauchen Updates. b) Sie schützen vor allen Angriffen. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nicht alle Angriffe abgedeckt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Antivirenprogramme?', 4, '[{"text": "Virendefinitionen", "correct": false, "because": "Notwendig für Erkennung"}, {"text": "Echtzeitüberwachung", "correct": false, "because": "Schützt proaktiv"}, {"text": "Maximale Speichergröße", "correct": true, "because": "Kein Schutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Erkennen Antivirenprogramme nur bekannte Malware?', 2, '[{"text": "Nein", "correct": true, "because": "Heuristik für neue Bedrohungen"}, {"text": "Ja", "correct": false, "because": "Erweiterte Erkennung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ansätze nutzen Antivirenprogramme?', 4, '[{"text": "Verhaltensanalyse", "correct": true, "because": "Erkennt verdächtige Aktivitäten"}, {"text": "Quarantäne", "correct": true, "because": "Isoliert Bedrohungen"}, {"text": "Visuelles Design", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Antivirenprogramme alle Bedrohungen stoppen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Begrenzte Wirksamkeit"}, {"text": "Ja", "correct": false, "because": "Nicht 100% abgedeckt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei Antivirenprogrammen?', 3, '[{"text": "Aktuelle Virendefinitionen", "correct": true, "because": "Schutz aktuell halten"}, {"text": "Schnelle Ladezeiten", "correct": false, "because": "Sekundär"}, {"text": "Grafische Gestaltung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Antivirenprogramme bieten Echtzeitschutz. b) Sie ersetzen Firewalls.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Firewalls ergänzen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktionen unterstützen Antivirenprogramme?', 5, '[{"text": "Phishing-Schutz", "correct": true, "because": "Erkennt betrügerische Links"}, {"text": "Malware-Entfernung", "correct": true, "because": "Beseitigt Infektionen"}, {"text": "Datenbankgröße", "correct": false, "because": "Nicht relevant"}, {"text": "Animationen", "correct": false, "because": "Kein Schutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Antivirenprogrammen unwichtig?', 3, '[{"text": "Scan-Frequenz", "correct": false, "because": "Erkennung optimieren"}, {"text": "Update-Häufigkeit", "correct": false, "because": "Schutz aktuell halten"}, {"text": "Schriftarten", "correct": true, "because": "Kein Sicherheitsaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Schützen Antivirenprogramme auch vor Phishing?', 3, '[{"text": "Ja", "correct": true, "because": "Viele bieten Phishing-Schutz"}, {"text": "Nein", "correct": false, "because": "Erweiterte Funktionen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Antivirenprogramme automatisch aktualisieren?', 2, '[{"text": "Ja", "correct": true, "because": "Meist automatische Updates"}, {"text": "Nein", "correct": false, "because": "Regelmäßige Aktualisierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element wähle ich für Antivirenprogramme?', 4, '[{"text": "Heuristische Analyse", "correct": true, "because": "Erkennt neue Bedrohungen"}, {"text": "Maximale Speichergröße", "correct": false, "because": "Irrelevant"}, {"text": "Grafisches Design", "correct": false, "because": "Kein Schutzfokus"}]');
